'use strict';

/**
 * clock.js — Injectable clock for the rate limiter.
 *
 * Production code uses the system clock.
 * Tests can inject a deterministic clock to avoid real-time waits
 * and to test window boundary behavior precisely.
 */

/**
 * Returns the current time as an integer Unix timestamp (seconds since epoch, UTC).
 * This is the default (production) clock.
 */
function systemClock() {
  return Math.floor(Date.now() / 1000);
}

module.exports = { systemClock };

'use strict';

/**
 * config.js — Customer and tier configuration for RelayAPI rate limiting.
 *
 * Design decisions (from Phase 1):
 * - Tier-based defaults with per-customer RPM overrides
 * - Quota resolved: customer.rpm (if set) → tier.rpm (fallback)
 * - No customer-specific code paths — all customers use the same resolution logic
 * - A quota change for any customer (including Northwind) is a config change, not a code change
 */

const tiers = {
  starter: { rpm: 60 },
  growth: { rpm: 300 },
  enterprise: { rpm: 300 },  // default for enterprise; individual customers can override
};

const customers = {
  'customer-1': {
    name: 'Acme Corp',
    tier: 'starter',
    // No rpm override → uses tier default (60 RPM)
  },
  'customer-2': {
    name: 'Beta Inc',
    tier: 'growth',
    // No rpm override → uses tier default (300 RPM)
  },
  'northwind': {
    name: 'Northwind Logistics',
    tier: 'enterprise',
    // No rpm override → uses tier default (300 RPM)
    // To accommodate the batch window: change this to  rpm: 1500
    // That is a COMMERCIAL decision, not an engineering one.
  },
};

/**
 * Resolve the RPM quota for a given customer ID.
 *
 * Resolution order:
 *   1. customer.rpm (explicit per-customer override)
 *   2. tiers[customer.tier].rpm (tier default)
 *
 * @param {string} customerId
 * @returns {{ rpm: number, tier: string, name: string } | null}
 *   null if customer is unknown
 */
function resolveQuota(customerId) {
  const customer = customers[customerId];
  if (!customer) {
    return null;
  }

  const tier = tiers[customer.tier];
  if (!tier) {
    return null;
  }

  const rpm = customer.rpm !== undefined ? customer.rpm : tier.rpm;

  return {
    customerId,
    name: customer.name,
    tier: customer.tier,
    rpm,
  };
}

/**
 * Get all configured customer IDs.
 * @returns {string[]}
 */
function getCustomerIds() {
  return Object.keys(customers);
}

module.exports = { tiers, customers, resolveQuota, getCustomerIds };

'use strict';

/**
 * redis-client.js — Redis connection module for RelayAPI.
 *
 * Design decisions:
 * - Single reusable Redis client module (not scattered through the app)
 * - The rate limiter receives the Redis client, not the connection details
 * - Connection failure is surfaced cleanly (not swallowed)
 * - The eventual rate limiter will use this client to execute Lua scripts atomically
 *
 * IMPORTANT ARCHITECTURAL NOTE:
 * The rate limiter must NOT implement:
 *     GET from Redis → decide in Node.js → INCR in Redis
 * That pattern reintroduces the race condition we designed away in Phase 1.
 * All rate-limit logic (GET + compare + conditional INCR + EXPIRE) MUST happen
 * inside a single atomic Redis Lua script.
 */

const Redis = require('ioredis');

/**
 * Create a Redis client connected to the specified host/port.
 *
 * @param {object} [options]
 * @param {string} [options.host='127.0.0.1']
 * @param {number} [options.port=6379]
 * @param {boolean} [options.lazyConnect=false] - If true, won't connect until first command
 * @returns {Redis} ioredis client instance
 */
function createRedisClient(options = {}) {
  const host = options.host || process.env.REDIS_HOST || '127.0.0.1';
  const port = options.port || parseInt(process.env.REDIS_PORT, 10) || 6379;
  const lazyConnect = options.lazyConnect || false;

  const client = new Redis({
    host,
    port,
    lazyConnect,
    maxRetriesPerRequest: 1,         // fail fast on connection issues
    retryStrategy(times) {
      // Retry with exponential backoff, max 3 seconds
      if (times > 5) return null;    // stop retrying after 5 attempts
      return Math.min(times * 200, 3000);
    },
    enableReadyCheck: true,
  });

  return client;
}

module.exports = { createRedisClient };

'use strict';

/**
 * rate-limiter.js — Rate limiter skeleton for RelayAPI.
 *
 * PHASE 2: SKELETON ONLY — The actual rate-limiting logic will be
 * implemented in Phase 3. This file establishes the module boundary
 * and interface that the server will use.
 *
 * DESIGN (from Phase 1, corrected):
 * - Algorithm: Fixed Window Counter (calendar-minute buckets, UTC)
 * - Counter: counts ACCEPTED requests only (not all attempts)
 * - Atomicity: ALL rate-limit logic runs inside a single Redis Lua script
 *   (GET + compare + conditional INCR + EXPIRE) — never split across
 *   Redis commands and Node.js application logic
 * - TTL: aligned with calendar-minute boundary + 1s safety margin
 * - Clock: injectable for deterministic testing
 *
 * The Lua script will be implemented in Phase 3.
 */

const { systemClock } = require('./clock');

/**
 * Create a rate limiter instance.
 *
 * @param {object} options
 * @param {Redis}  options.redisClient - ioredis client instance
 * @param {Function} [options.clock=systemClock] - Returns current Unix timestamp (seconds)
 * @returns {object} Rate limiter with checkLimit() method
 */
function createRateLimiter({ redisClient, clock = systemClock } = {}) {
  // Phase 3 will implement:
  // - Lua script registration
  // - checkLimit(customerId, limit) → { allowed, current, limit, retryAfter }
  // - Express middleware

  return {
    /**
     * Check whether a request from the given customer should be allowed.
     *
     * STUB — always allows. Will be replaced in Phase 3.
     *
     * @param {string} customerId
     * @param {number} limit - RPM quota for this customer
     * @returns {Promise<{allowed: boolean, current: number, limit: number, remaining: number, retryAfter: number|null, resetAt: number}>}
     */
    async checkLimit(customerId, limit) {
      // TODO Phase 3: Replace with atomic Lua script execution
      const now = clock();
      const windowEnd = (Math.floor(now / 60) + 1) * 60;
      return {
        allowed: true,
        current: 0,
        limit,
        remaining: limit,
        retryAfter: null,
        resetAt: windowEnd,
      };
    },
  };
}

module.exports = { createRateLimiter };

'use strict';

/**
 * app.js — Express application factory for RelayAPI.
 *
 * Separated from server.js so that:
 * - Tests can create an app instance without starting a listening server
 * - Multiple server instances (Node 1, 2, 3) share the same app logic
 */

const express = require('express');
const { resolveQuota } = require('./config');

/**
 * Create the Express application.
 *
 * @param {object} options
 * @param {object} options.rateLimiter - Rate limiter instance (from createRateLimiter)
 * @param {string} [options.nodeId='unknown'] - Identifier for this node (for observability)
 * @returns {express.Application}
 */
function createApp({ rateLimiter, nodeId = 'unknown' } = {}) {
  const app = express();

  // ─── Health endpoint ──────────────────────────────────────────────
  // Does NOT depend on the rate limiter or Redis.
  // Reason: health checks should reflect whether the HTTP server is alive,
  // not whether downstream dependencies are healthy. A separate /ready
  // endpoint could check Redis if needed for production use.
  app.get('/health', (req, res) => {
    res.status(200).json({
      status: 'ok',
      node: nodeId,
      timestamp: new Date().toISOString(),
    });
  });

  // ─── API endpoint (mock resource) ─────────────────────────────────
  // This represents the actual API that customers call.
  // Rate limiting will be applied here (Phase 3).
  app.get('/api/v1/resource', async (req, res) => {
    const customerId = req.headers['x-customer-id'];

    // Validate customer identity
    if (!customerId) {
      return res.status(401).json({
        error: 'missing_customer_id',
        message: 'X-Customer-Id header is required.',
      });
    }

    const quota = resolveQuota(customerId);
    if (!quota) {
      return res.status(401).json({
        error: 'unknown_customer',
        message: `Unknown customer: ${customerId}`,
      });
    }

    // Rate limiting check (Phase 3 will make this real)
    try {
      const result = await rateLimiter.checkLimit(customerId, quota.rpm);

      // Set rate-limit headers on every response
      res.set('X-RateLimit-Limit', String(result.limit));
      res.set('X-RateLimit-Remaining', String(result.remaining));
      res.set('X-RateLimit-Reset', String(result.resetAt));
      res.set('X-Served-By', nodeId);

      if (!result.allowed) {
        res.set('Retry-After', String(result.retryAfter));
        return res.status(429).json({
          error: 'rate_limit_exceeded',
          message: `Rate limit exceeded. Try again in ${result.retryAfter} seconds.`,
          retry_after: result.retryAfter,
          limit: result.limit,
          remaining: 0,
        });
      }

      // Success — return mock resource
      return res.status(200).json({
        data: 'ok',
        customer: customerId,
        node: nodeId,
        rate_limit: {
          limit: result.limit,
          remaining: result.remaining,
          reset: result.resetAt,
        },
      });
    } catch (err) {
      // Redis connection failure → fail closed with 503
      // (Phase 1 decision: CTO prefers over-reject over under-limit)
      console.error(`[${nodeId}] Rate limiter error:`, err.message);
      return res.status(503).json({
        error: 'service_unavailable',
        message: 'Rate limiting service is temporarily unavailable.',
      });
    }
  });

  return app;
}

module.exports = { createApp };

'use strict';

/**
 * server.js — Entry point for the RelayAPI rate-limiter service.
 *
 * Starts an Express HTTP server connected to Redis.
 * Designed to run as multiple independent instances behind a load balancer.
 *
 * Environment variables:
 *   PORT       — HTTP port (default: 3000)
 *   NODE_ID    — Identifier for this node (default: node-{PORT})
 *   REDIS_HOST — Redis hostname (default: 127.0.0.1)
 *   REDIS_PORT — Redis port (default: 6379)
 */

const { createApp } = require('./app');
const { createRedisClient } = require('./redis-client');
const { createRateLimiter } = require('./rate-limiter');

const PORT = parseInt(process.env.PORT, 10) || 3000;
const NODE_ID = process.env.NODE_ID || `node-${PORT}`;

async function main() {
  console.log(`[${NODE_ID}] Starting RelayAPI rate-limiter service...`);

  // Connect to Redis
  const redisClient = createRedisClient();

  redisClient.on('connect', () => {
    console.log(`[${NODE_ID}] Connected to Redis at ${redisClient.options.host}:${redisClient.options.port}`);
  });

  redisClient.on('error', (err) => {
    console.error(`[${NODE_ID}] Redis error:`, err.message);
  });

  // Create rate limiter (Phase 3 will implement the real logic)
  const rateLimiter = createRateLimiter({ redisClient });

  // Create and start Express app
  const app = createApp({ rateLimiter, nodeId: NODE_ID });

  const server = app.listen(PORT, () => {
    console.log(`[${NODE_ID}] Listening on port ${PORT}`);
    console.log(`[${NODE_ID}] Health: http://localhost:${PORT}/health`);
    console.log(`[${NODE_ID}] API:    http://localhost:${PORT}/api/v1/resource`);
  });

  // Graceful shutdown
  function shutdown(signal) {
    console.log(`[${NODE_ID}] Received ${signal}, shutting down...`);
    server.close(() => {
      redisClient.disconnect();
      console.log(`[${NODE_ID}] Shut down cleanly.`);
      process.exit(0);
    });
  }

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

main().catch((err) => {
  console.error('Fatal error:', err);
  process.exit(1);
});

# nginx.conf — Round-robin load balancer for RelayAPI
#
# Routes requests across three stateless application nodes.
# No sticky sessions. Pure round-robin distribution.

events {
    worker_connections 1024;
}

http {
    upstream relayapi {
        # Round-robin (default) — no sticky sessions
        server node-1:3000;
        server node-2:3000;
        server node-3:3000;
    }

    server {
        listen 80;

        location / {
            proxy_pass http://relayapi;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            # Pass through X-Customer-Id from the client
            proxy_set_header X-Customer-Id $http_x_customer_id;
        }
    }
}

